(122, 1, 'load_content_data', 'if($_GET[\'load_content_data\'] == \'#Enter Your Content Name#\'  ){\nob_end_clean();\n $response_load_content = jlon_create($response_load_content); \n$response_load_content -> echo_type_div= \"Yes\";\n//$response_load_content -> echo_type_modal= \"Yes\";\n//$response_load_content -> content_form .= \"#Enter Your Form Parameter#\";\n//$response_load_content -> content_header .= \"#Enter Your Content Header#\";\n$response_load_content -> content_body .= \"#Enter Your Content Body#\";\n//$response_load_content -> content_footer .= \"#Enter Your Content footer#\";\n//$response_load_content -> content_jquery .= \"#Enter Your Jquery parameter#\";\necho jlon_encode($response_load_content);\nexit();\n\n}\n\necho load_content_data(\'content_name=#Your Content Name#, onload=yes\');', 'content_data', NULL, '2024-10-26 11:07:36', NULL),
(233, 1, 'post_content_data', 'if ($_POST[\'post_content_data\']  == \'#Enter Your Element ID#\'){\n    ob_end_clean();  \n$response_post_content = jlon_create($response_post_content); \n$response_post_content -> content_body .=\'#Enter the body to display#\' ;\n $response_post_content ->echo_type_modal =\'Yes\';\n//$response_post_content ->reload_content_data =\'#Enter the Content Name to Reload#\';\n  \necho jlon_encode($response_post_content);\nexit();\n} ', 'content_data', NULL, '2024-10-26 11:07:36', NULL),
(256, 1, 'edit_content_data', 'if($_GET[\"edit_content_data\"] == \'#Enter Your Content Name#\'){\n    ob_end_clean();\n$check_url = validate_url();\nif ($check_url  == \'success\'){ \n//this is where u put the code\n\n $response_edit_content = jlon_create($response_edit_content); \n$response_edit_content -> content_header =\'Edit Your Form Object\';\n \n$response_edit_content -> content_body .= $lifetech_modal_body;\n$response_edit_content -> content_footer .= $lifetech_modal_footer;\n$response_edit_content -> content_jquery .= $lifetech_modal_jquery ;\n$response_edit_content -> echo_type_modal .= \"Yes\";\necho jlon_encode($response_edit_content);\n    exit();\n\n    }else{ \n\n$response_edit_content = jlon_create($response_edit_content);\n$response_edit_content -> content_body .= \'Your Id is not equivalent to your Pin  \'; \necho jlon_encode($response_edit_content); \nexit();\n\n\n}\n}', 'content_data', NULL, '2024-10-26 11:07:36', NULL),
