(521, 1, 'lifetech_obj_db_select', '$urid = \'4\';\n$parameter_select_obj = \"\'table_name = user_role\' ,  \'table_fieldname =urid\', \'table_where =_urid\', \'#*table_order=ORDER BY sn\', \'#*table_limit= LIMIT 10\'\";\n$response_select_obj = lifetech_obj_db_select($parameter_select_obj); \n if ($response_select_obj -> rowCount() > 0 ) {\n    while ($load_select_obj = $response_select_obj -> fetch() ){\n       echo $load_select_obj ->urid; //take note, it is those fields inside your table_fieldname that u can echo \n    }\n}\n', 'Lifefunction', NULL, '2024-10-26 11:07:36', NULL),
