(601, 1, 'lifetech_obj_db_create', '$lifech_create_obj = getLifetechClass();\r\n$lifech_create_obj -> table_name =\'#Enter the table name#\';\r\n$lifech_create_obj -> table_fieldname =\"success_reponse, already_exist, element_empty, lifetech_general_id, lifetech_status\";\r\n$lifech_create_obj -> table_fieldtype =\"varchar , text, text, bigint, varchar\";\r\n$lifech_create_obj -> table_fieldlength =\"120 , 80, 80, 15,2\";                   \r\n$lifech_create_obj_feedback = $lifech_create_obj -> lifetech_obj_db_create();\r\necho $lifech_create_obj_feedback;', 'Lifefunction', NULL, '2024-10-26 11:07:36', NULL),
(623, 1, 'lifetech_obj_db_alter', '\r\n$lifech_alter_obj = getLifetechClass();\r\n$lifech_alter_obj -> table_name =\'#Enter the table name#\'; \r\n$lifech_alter_obj -> table_fieldname =\"lifetech_questions\";\r\n$lifech_alter_obj -> table_fieldtype =\"varchar\";\r\n$lifech_alter_obj -> table_fieldlength =\"120\"; \r\n$lifech_alter_obj -> table_altertype =\"ADD\"; //   $lifech_alter_obj -> table_altertype =\"CHANGE\"; if u want to edit the field name\r\n$lifech_alter_obj_feedback = $lifech_alter_obj -> lifetech_obj_db_alter();\r\necho $lifech_alter_obj_feedback;', 'Lifefunction', NULL, '2024-10-26 11:07:36', NULL),
