(646, 1, 'lifetech_obj_foreign_record', '//foreign record is used to use a particular key to fetch a value from the records\n//the table_labelvalue is what is will return, while the table_key is the key index to access each record\n\n$parameter_foreign = \"\'table_name= #Enter Your Table Name#\', \'table_labelvalue=compHead . qrtName \', \'table_key=department_id\'\";\n$get_foreign_feedback= lifetech_obj_foreign_record($parameter_foreign);\n$index_to_fetch=\'12384726\';\necho $get_foreign_feedback ->$index_to_fetch;', 'Lifefunction', NULL, '2024-10-26 11:07:36', NULL),
