(715, 1, 'lifetech_obj_hyperlink($parameter)', '//this function is to diplay an hyperlink for the users\r\n$parameter_hyper = \"\'title=#enter your link titel#\', \'module_name=#Enter the Module Name of the link#\',\'content_name=#Enter the Content Name #\',\'caption=#Enter link Caption#\',\'get_value=#*Enter the GET value for the link#\',\'target=#*Enter the target#\',\'server_root=#*Enter the link Http Address#\',  \";\r\n$response_obj_hyper= lifetech_obj_hyperlink($parameter_hyper);\r\necho $response_obj_hyper;\r\n', 'Lifefunction', NULL, '2024-10-26 11:07:36', NULL),
(718, 1, 'Controller GET', '//this is used to determine if the request from the frontend is GET method and to execute the codes\n//ob_end_clean is used to flush existing output and exit() is used to terminate and return to frontend code\n\nif(Controller::get(\'userRegSubmit\')){\n    ob_end_clean();\n     //write code here\n   exit();\n}\n\n/*\n //if the get parameter has value then you will use two parameter instead of ne \nif(Controller::get(\'userRegSubmit\', \'Submitted\')){\n    ob_end_clean();\n     //write code here\n   exit();\n}\n*/', 'Model_and_Controller', NULL, '2024-11-28 14:51:53', NULL),
(721, 1, 'lifetech_obj_url_encrypt()', '//This is a function that u supply your ID and it return matching PIN and KEY that u can use to know if the ID is tampered on the URL Address\r\n        $load_obj_url_encrypt = getLifetechClass();\r\n          $load_obj_url_encrypt -> lifetech_general_id =  \'#Enter the Unique Value U want to genrate Pin and Key for\'; \r\n          $load_obj_url_encrypt -> lifetech_obj_url_encrypt();\r\n            $Url_Pin  = $load_obj_url_encrypt -> urlpin;  \r\n            $Url_Key = $load_obj_url_encrypt -> urlkey;   ', 'Lifefunction', NULL, '2024-10-26 11:07:36', NULL),
(722, 1, 'Controller PostAND', '//this is when your are determining when two parameters is validated before executing a controller\r\n//ob_end_clean is used to flush existing output and exit() is used to terminate and return to frontend code\r\n\r\n//PHP syntax is if($_POST[\'userRegSubmit\']==\"Submitted\" && $_POST[\'api_key_status\']==\"Yes\")\r\n //if the get parameter has value then you will use two parameter instead of ne \r\nif(Controller::postAnd(\'userRegSubmit\', \'Submitted\')->get(\'api_key_status\',\'Yes\')){\r\n    ob_end_clean();\r\n     //write code here\r\n   exit();\r\n} \r\n\r\n', 'Model_and_Controller', NULL, '2024-11-28 15:06:55', NULL),
(726, 1, 'lifetech_obj_url_decrypt()', '//This is the function that decrypt the  ID , PIN and KEY to know if the ID is tampered on the URL Address\r\n$load_obj_url_decrypt = getLifetechClass(); \r\n$load_obj_url_decrypt -> lifetech_general_id = #The general ID u supplied to get the PIN and Key#; \r\n$load_obj_url_decrypt -> urlpin = $Url_Pin ; \r\n$load_obj_url_decrypt -> urlkey = $Url_Key; \r\n$load_obj_url_decrypt -> lifetech_obj_url_decrypt();\r\nif ( $load_obj_url_decrypt -> response == \'success\'){ \r\necho \'Your Pin is Correct\';\r\n}else{\r\n  echo \'Your Injectecd Your Pin \';  \r\n}', 'Lifefunction', NULL, '2024-10-26 11:07:36', NULL),
(744, 1, 'Controller POST', '//this is used to determine if the request from the frontend is POST method and to execute the codes\r\n//ob_end_clean is used to flush existing output and exit() is used to terminate and return to frontend code\r\n\r\nif(Controller::post(\'userRegSubmit\')){\r\n    ob_end_clean();\r\n     //write code here\r\n   exit();\r\n}\r\n\r\n/*\r\n //if the post parameter has value then you will use two parameter instead of ne \r\nif(Controller::post(\'userRegSubmit\', \'Submitted\')){\r\n    ob_end_clean();\r\n     //write code here\r\n   exit();\r\n}\r\n*/', 'Model_and_Controller', NULL, '2024-11-28 14:51:53', NULL),
(767, 1, 'Controller GetOR', '//this is when your are determining either one or two paramaters is validated before executing a controller\r\n//ob_end_clean is used to flush existing output and exit() is used to terminate and return to frontend code\r\n\r\n//PHP syntax is if($_POST[\'userRegSubmit\']==\"Submitted\" || $_POST[\'api_key_status\']==\"Yes\")\r\n //if the get parameter has value then you will use two parameter instead of ne \r\nif(Controller::getOr(\'userRegSubmit\', \'Submitted\')->get(\'api_key_status\',\'Yes\')){\r\n    ob_end_clean();\r\n     //write code here\r\n   exit();\r\n} \r\n\r\n', 'Model_and_Controller', NULL, '2024-11-28 15:06:55', NULL),
(773, 1, 'Model Creation', '//this is the point you create a model of your database table name which must be extended by model class\n//DbTableName is the table model you are creating\n//function if class_exists is to check if the model has already been created so that it will not crash your application\n\n\nif (class_exists(\'DbTableName\')) {  \n}else{ \nclass DbTableName extends Model{}\n}\n', 'Model_and_Controller', NULL, '2024-11-28 14:51:53', NULL),
(792, 1, 'Controller GetAND', '//this is when your are determining when two parameters is validated before executing a controller\r\n//ob_end_clean is used to flush existing output and exit() is used to terminate and return to frontend code\r\n\r\n//PHP syntax is if($_POST[\'userRegSubmit\']==\"Submitted\" && $_POST[\'api_key_status\']==\"Yes\")\r\n //if the get parameter has value then you will use two parameter instead of ne \r\nif(Controller::getAnd(\'userRegSubmit\', \'Submitted\')->get(\'api_key_status\',\'Yes\')){\r\n    ob_end_clean();\r\n     //write code here\r\n   exit();\r\n} \r\n\r\n', 'Model_and_Controller', NULL, '2024-11-28 15:06:55', NULL),
(797, 1, 'Controller PostOR', '//this is when your are determining either one or two paramaters is validated before executing a controller\r\n//ob_end_clean is used to flush existing output and exit() is used to terminate and return to frontend code\r\n\r\n//PHP syntax is if($_POST[\'userRegSubmit\']==\"Submitted\" || $_POST[\'api_key_status\']==\"Yes\")\r\n //if the get parameter has value then you will use two parameter instead of ne \r\nif(Controller::postOr(\'userRegSubmit\', \'Submitted\')->get(\'api_key_status\',\'Yes\')){\r\n    ob_end_clean();\r\n     //write code here\r\n   exit();\r\n} \r\n\r\n', 'Model_and_Controller', NULL, '2024-11-28 15:06:55', NULL),
(802, 1, 'lifetech_get_password($param)', '//This is a function that will get u the Salt and Encrypted Value of a given Password\r\n$password_value = \'#Enter Your Password Value#\';\r\n$response_password_value = lifetech_get_password($password_value);\r\n$password = $response_password_value ->lifetech_password;\r\n$salt =   $response_password_value ->salt;', NULL, NULL, '2024-10-26 11:07:36', NULL),
(814, 1, 'lifetech_email_exist($param)', '//This function will check whether Your Email or Username Already Exist on Your Website\r\n$email_toCheck = \'#enter the email you want to Check#\';\r\n$response_email_toCheck = lifetech_email_exist($email_toCheck);\r\n\r\nif($response_email_toCheck[\'response\'] == \"Yes\"){\r\n    echo \'Your Email Already Exist\';\r\n}else{\r\n    echo \'Your Email is not Existing\';\r\n}\r\n', NULL, NULL, '2024-10-26 11:07:36', NULL),
(822, 1, 'JLON Object RM with Data', '//JLON; Javascript Lifetech Object Notation, this Model is used to make a varriable, array and json data to an Object, for usage on LIFETECH \n// We have JLON CREATE, JLON ENCODE and JLON DECODE.\n\n//1. JLON CREATE is when you are making a varriable an instance of an OBject for particular Usage\n$object_name jlon_create(\'#Enter Object Name#\');\n//once your object name is created , then u can be assigning properties to it anyhowe.g;\n$object_name -> surname = \'My surname\';\n//also you can retrieve or read value from you Object Model\n$staff_surname = $object_name -> surname ;\n\n//2. JLON ENCODE is when you want to convert existing array value or json data to JLON object\n$my_array_value = array(\"username\"=>\'ad01\',\"firstname\"=>\'ademide\'\"surname\"=>\'akinde\');\n $my_obj_staff = jlon_encode($my_array_value);\n//automatically your array has converted to the object Model, which can also be sent to other Prog Lang as JSON file\n\n\n\n//3. JLON DECODE is when you want to get value from the encoded JLON object, then u will decode before u can access it\n$decode_my_obj_staff = jlon_decode($$my_obj_staff)\n//automatically your object Model has decode to the object Usage, you can now be calling on the properties\necho $decode_my_obj_staff -> surname;', 'JLON', NULL, '2024-10-26 11:07:36', NULL),
(905, 1, 'JLON Model to Interact With Database', '//This Abstraction model get data from the database and render it to the view template in order not to be goin to the DB everytime\r\n//we have JLON CREATE , JLON PROCESS, JLON READ, JLON WRITE, INDEXOF, and HEADEROF\r\n//1. JLON CREATE , to create the object name\r\n$object_name = jlon_create(\'object_name\');\r\n\r\n//2. JLON PROCESS is gettin all your table data to and object to u can call on\r\n//Note: the object name in JLON process must be same thing in Jlon create, and u are going to use it all through\r\n$parameter_jlon_process = \"\'table_name=#Enter Table name#\',   \'object_key=lifetech_general_id\', \'fieldname=site_name, address2 \',  \'object_name= #Enter Object Name#\'\";\r\n$jlon_process_jlon_lifetech_site_table = jlon_process($parameter_jlon_process);\r\n\r\n//3. JLON READ , when u want to read a value from the OBJECT Model of jLON, U will need the Record ID and fieldName   \r\n$surname =  $object_name ->jlon_read($record_id,$fieldName);\r\n\r\n//4. JLON WRITE , when u want to write back to the ORM, U will need RecordID, fieldName and Value to write\r\n$object_name-> jlon_write($record_id, $fieldName, $Value);\r\n\r\n//5. INDEXOF, this will tell you all the record ID in the Object Model\r\n$index_of_ID = indexof(\'#Enter ObjetName#\');\r\nforeach($index_of_ID as $index_of_value){\r\n    echo $index_of_value;\r\n}\r\n\r\n//6. HEADEROF, this function will tell you all header in the Object Model\r\n$header_of_ID = indexof(\'#Enter ObjetName#\');\r\nforeach($header_of_ID as $header_of_value){\r\n    echo $header_of_value;\r\n}', 'JLON', NULL, '2024-10-26 11:07:36', NULL),
(909, 1, ' If statement', '\n{% if($username== \"You\"):  %}\n <div>\n  this is my name {! $username  !}\n </div>\n{% else: %}\n <div>\n  this is my other name {! $username  !}\n </div>\n{% endif;  %}', 'LifeRazor', NULL, '2024-11-28 16:29:33', NULL),
(930, 1, 'while statement', '{% counter = 2; %}\r\n{% while($counter < 5):  %}\r\n   <div>\r\n    No: {! $counter !}\r\n  </div>\r\n{% counter ++ %}\r\n{%.  endwhile: %}', 'LifeRazor', NULL, '2024-11-28 16:33:38', NULL),
(955, 1, 'foreach statement', '\r\n\r\n{% foreach($studentRecords as $students):  %}\r\n  <div>email: {! $students->email !}\r\n  </div>\r\n{%.  endforeach;  %}', 'LifeRazor', NULL, '2024-11-28 16:33:38', NULL),
(992, 1, 'LifeRazor Print', '// variable in liferazor start with $ sign\r\n\r\n{! \"hell World!!\" !}\r\n\r\n// {! $username !}', 'LifeRazor', NULL, '2024-11-28 16:29:33', NULL),
(1001, 1, 'Select', '// to load all your table records\r\n//Select * from tbl_name;\r\n$user->get()\r\n\r\n//to load based on parameters \r\n$user->select()->where(‘a’ , ’=’ , ’b’)-> orderby(‘username’)->limit(5)->get();\r\n\r\n/*if you want to view the sql statement just change the last chain to tosql\r\n$user->select()->where(‘a’ , ’=’ , ’b’)-> orderby(‘username’)->limit(5)->tosql();\r\n*/', 'MapLite', NULL, '2024-11-28 16:48:36', NULL),
